def parse(text: str) -> dict[str, dict[str, str]]:
    """Parse INI text."""
    sections: dict[str, dict[str, str]] = {}
    current: str | None = None
    continuation: str | None = None

    for lineno, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()

        # Blank and comment lines are ignored and break any continuation.
        if not stripped or stripped[0] in "#;":
            continuation = None
            continue

        # An indented line directly after a key (or its continuation) extends
        # that key's value, even if it looks like a section or key/value pair.
        if continuation is not None and line[0].isspace():
            assert current is not None
            sections[current][continuation] += "\n" + stripped
            continue

        continuation = None

        # Section header, with optional surrounding whitespace.
        if stripped.startswith("[") and stripped.endswith("]"):
            current = stripped[1:-1].strip()
            sections.setdefault(current, {})
            continue

        # Key/value pair: split at the first '=' or ':', whichever is first.
        equals = stripped.find("=")
        colon = stripped.find(":")
        if equals == -1:
            separator = colon
        elif colon == -1:
            separator = equals
        else:
            separator = min(equals, colon)

        if separator == -1:
            raise ParseError(lineno, "expected a section or a key/value pair")

        key = stripped[:separator].strip().lower()
        value = stripped[separator + 1 :].strip()

        if not key:
            raise ParseError(lineno, "empty key")
        if current is None:
            raise ParseError(lineno, "key outside of a section")

        # Assignment to an existing key replaces the value but keeps its
        # original position in the dict.
        sections[current][key] = value
        continuation = key

    return _interpolate(sections)


def _interpolate(sections: dict[str, dict[str, str]]) -> dict[str, dict[str, str]]:
    """Return a copy of *sections* with every value fully interpolated."""
    cache: dict[tuple[str, str], str] = {}
    stack: list[tuple[str, str]] = []
    positions: dict[tuple[str, str], int] = {}

    def resolve(section: str, key: str) -> str:
        node = (section, key)
        if node in cache:
            return cache[node]
        if node in positions:
            cycle = stack[positions[node] :] + [node]
            path = " -> ".join(f"{sec}:{name}" for sec, name in cycle)
            raise InterpolationError(f"circular reference: {path}")

        positions[node] = len(stack)
        stack.append(node)
        try:
            value = interpolate_value(sections[section][key], section)
        finally:
            stack.pop()
            del positions[node]

        cache[node] = value
        return value

    def interpolate_value(raw: str, section: str) -> str:
        out: list[str] = []
        i = 0
        length = len(raw)
        while i < length:
            char = raw[i]
            if char != "$":
                out.append(char)
                i += 1
                continue

            # "$$" is an escaped dollar sign and shields what follows.
            if raw.startswith("$$", i):
                out.append("$")
                i += 2
                continue

            if raw.startswith("${", i):
                end = raw.find("}", i + 2)
                if end != -1:
                    reference = raw[i + 2 : end]
                    if ":" in reference:
                        section_part, key_part = reference.split(":", 1)
                        target_section = section_part.strip()
                        target_key = key_part.strip().lower()
                    else:
                        target_section = section
                        target_key = reference.strip().lower()

                    if target_section not in sections:
                        raise InterpolationError(
                            f"unknown section {target_section!r} in "
                            f"${{{reference}}}"
                        )
                    if target_key not in sections[target_section]:
                        raise InterpolationError(
                            f"unknown key {target_key!r} in section "
                            f"{target_section!r} for ${{{reference}}}"
                        )
                    out.append(resolve(target_section, target_key))
                    i = end + 1
                    continue

            # Any other '$' (including an unclosed '${') is literal.
            out.append("$")
            i += 1

        return "".join(out)

    return {
        section: {key: resolve(section, key) for key in values}
        for section, values in sections.items()
    }
